using System;
using System.Threading;
using System.Threading.Tasks;
using Contoso.Api.Orders;
using Microsoft.Extensions.Logging;

namespace Contoso.Worker.Jobs;

/// <summary>
/// Re-sends the orders whose first delivery failed, oldest first, a batch at
/// a time. The scheduler runs it every five minutes.
/// </summary>
public sealed class Retry
{
    private const int BatchSize = 100;

    /// <summary>The orders service, through the api's own client.</summary>
    private readonly IOrderClient _orders;
    private readonly ILogger<Retry> _log;

    public Retry(IOrderClient orders, ILogger<Retry> log)
    {
        _orders = orders;
        _log = log;
    }

    public async Task RunAsync(OutboxStore outbox, CancellationToken cancel)
    {
        foreach (var id in await outbox.FailedAsync(BatchSize, cancel))
        {
            var order = await _orders.GetAsync(id, cancel);
            if (order is null)
            {
                _log.LogWarning("Order {Id} is gone; dropping it from the outbox", id);
                await outbox.DropAsync(id, cancel);
                continue;
            }
            await outbox.ResendAsync(order, cancel);
        }
    }
}

using System;
using System.Net;
using System.Net.Http;
using System.Net.Http.Json;
using System.Threading;
using System.Threading.Tasks;

namespace Contoso.Api.Orders;

/// <summary>Calls the orders service, retrying a 429 up to five times.</summary>
public sealed class OrderClient(HttpClient http) : IOrderClient
{
    private const int MaxAttempts = 5;

    public async Task<Order?> GetAsync(int id, CancellationToken cancel)
    {
        for (var attempt = 1; ; attempt++)
        {
            using var response = await http.GetAsync($"orders/{id}", cancel);
            if (response.StatusCode == HttpStatusCode.TooManyRequests && attempt < MaxAttempts)
            {
                await Task.Delay(Backoff(response, attempt), cancel);
                continue;
            }
            if (response.StatusCode == HttpStatusCode.NotFound)
            {
                return null;
            }
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadFromJsonAsync<Order>(cancel);
        }
    }

    /// <summary>Retry-After when the service sends one, else 2^attempt seconds.</summary>
    internal static TimeSpan Backoff(HttpResponseMessage response, int attempt) =>
        response.Headers.RetryAfter?.Delta ?? TimeSpan.FromSeconds(Math.Pow(2, attempt));
}

