namespace Contoso.Api.Orders;

/// <summary>Calls the orders service, retrying a 429 up to five times.</summary>
public sealed class OrderClient(HttpClient http) : IOrderClient
{
    private const int MaxAttempts = 5;

    public async Task<Order?> GetAsync(int id, CancellationToken cancel)
    {
        for (var attempt = 1; ; attempt++)
        {
            using var response = await http.GetAsync($"orders/{id}", cancel);
            if (response.StatusCode == HttpStatusCode.TooManyRequests && attempt < MaxAttempts)
            {
                await Task.Delay(Backoff(response, attempt), cancel);
                continue;
            }
            if (response.StatusCode == HttpStatusCode.NotFound)
            {
                return null;
            }
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadFromJsonAsync<Order>(cancel);
        }
    }

    /// <summary>
    /// Retry-After when the service sends one, else 2^attempt seconds plus
    /// up to as much again at random, so clients that failed together do not
    /// retry together.
    /// </summary>
    internal static TimeSpan Backoff(HttpResponseMessage response, int attempt)
    {
        var seconds = Math.Pow(2, attempt);
        var jitter = Random.Shared.NextDouble() * seconds;
        return response.Headers.RetryAfter?.Delta ?? TimeSpan.FromSeconds(seconds + jitter);
    }
}

